const systemState = $input.first().json || {};
const isPaused = systemState.is_paused === true || systemState.is_paused === 'true';

console.log('🔍 Agent 1: System state check - is_paused:', isPaused);

if (isPaused) {
  console.log('⏸️ Agent 1: System is PAUSED. Skipping this run.');
  console.log('   Paused at:', systemState.paused_at);
  console.log('   Paused by:', systemState.paused_by);
}

return [{
  json: {
    isPaused: isPaused,
    pausedAt: systemState.paused_at || null,
    pausedBy: systemState.paused_by || null
  }
}];

const queueItems = $input.all().map(i => i.json);
const hasQueuedTopic = queueItems.length > 0 && queueItems[0].topic;

console.log('📋 Agent 1: Queue check - items found:', queueItems.length);
if (hasQueuedTopic) {
  console.log('✅ Agent 1: Found queued topic:', queueItems[0].topic);
}

return [{
  json: {
    hasQueuedTopic: hasQueuedTopic,
    queuedItem: hasQueuedTopic ? queueItems[0] : null
  }
}];

const data = $input.first().json;
const queuedItem = data.queuedItem;

const timestamp = new Date().toISOString();

console.log('🎯 Agent 1: Processing queued topic:', queuedItem.topic);

return [{
  json: {
    topic: queuedItem.topic,
    url: queuedItem.url || '',
    style: 'accessible-explanation',
    length: 'short',
    angle: 'general overview',
    timestamp: timestamp,
    phase: 'PHASE 5 - From Topic Queue',
    source: queuedItem.source || 'telegram',
    priority: queuedItem.priority || 1,
    queueId: queuedItem.id
  }
}];

const allItems = $input.all();
console.log('✅ HackerNews: Received', allItems.length, 'story IDs');

const allStoryIds = allItems.map(item => item.json);
const topIds = allStoryIds.slice(0, 30);
console.log('✅ HackerNews: Selected top 30 IDs');

return topIds.map(id => ({
  json: {
    storyId: id
  }
}));

const stories = $input.all();
console.log('✅ HackerNews: Fetched', stories.length, 'story details');

return [{
  json: {
    source: 'hackernews',
    stories: stories.map(item => ({
      title: item.json.title || '',
      url: item.json.url || '',
      score: item.json.score || 0,
      id: item.json.id,
      source: 'hackernews'
    })).filter(s => s.title && s.url)
  }
}];

const response = $input.first().json;
const posts = response?.data?.children || [];

console.log('✅ Reddit: Received', posts.length, 'posts');

// Filter for external links (not self posts)
const externalPosts = posts
  .map(p => p.data)
  .filter(p => !p.is_self && p.url && !p.url.includes('reddit.com'))
  .map(p => ({
    title: p.title || '',
    url: p.url || '',
    score: p.score || 0,
    subreddit: p.subreddit,
    source: 'reddit'
  }));

console.log('✅ Reddit: Filtered to', externalPosts.length, 'external links');

return [{
  json: {
    source: 'reddit',
    stories: externalPosts
  }
}];

const stories = $input.first().json || [];

console.log('✅ Lobsters: Received', stories.length, 'stories');

// Take top 20 stories with external URLs
const topStories = stories
  .slice(0, 20)
  .filter(s => s.url && !s.url.includes('lobste.rs'))
  .map(s => ({
    title: s.title || '',
    url: s.url || '',
    score: s.score || 0,
    tags: s.tags || [],
    source: 'lobsters'
  }));

console.log('✅ Lobsters: Filtered to', topStories.length, 'external links');

return [{
  json: {
    source: 'lobsters',
    stories: topStories
  }
}];

const response = $input.first().json;
const tweets = response?.data || [];

console.log('✅ Twitter: Received', tweets.length, 'tweets');

// Extract linked URLs from tweets
const twitterStories = [];

tweets.forEach(tweet => {
  const urls = tweet.entities?.urls || [];
  const metrics = tweet.public_metrics || {};

  urls.forEach(urlEntity => {
    // Skip twitter.com and t.co links
    const expandedUrl = urlEntity.expanded_url || urlEntity.url || '';
    if (expandedUrl && !expandedUrl.includes('twitter.com') && !expandedUrl.includes('t.co')) {
      twitterStories.push({
        title: urlEntity.title || tweet.text?.substring(0, 100) || 'Twitter Link',
        url: expandedUrl,
        score: (metrics.like_count || 0) + (metrics.retweet_count || 0) * 2,
        source: 'twitter'
      });
    }
  });
});

console.log('✅ Twitter: Extracted', twitterStories.length, 'external links');

return [{
  json: {
    source: 'twitter',
    stories: twitterStories
  }
}];

// Collect stories from all sources
const hnData = $("Format HN Stories").first()?.json || {stories: []};
const redditData = $("Format Reddit Stories").first()?.json || {stories: []};
const lobstersData = $("Format Lobsters Stories").first()?.json || {stories: []};
const twitterData = $("Format Twitter Stories").first()?.json || {stories: []};

const allStories = [
  ...hnData.stories,
  ...redditData.stories,
  ...lobstersData.stories,
  ...twitterData.stories
];

console.log('🔀 Merge: Total stories before dedup:', allStories.length);
console.log('   - HackerNews:', hnData.stories.length);
console.log('   - Reddit:', redditData.stories.length);
console.log('   - Lobsters:', lobstersData.stories.length);
console.log('   - Twitter:', twitterData.stories.length);

// Deduplicate by URL (normalize URLs first)
function normalizeUrl(url) {
  try {
    const u = url.toLowerCase()
      .replace(/^https?:\/\//, '')
      .replace(/^www\./, '')
      .replace(/\/$/, '');
    return u;
  } catch {
    return url;
  }
}

const seen = new Set();
const uniqueStories = allStories.filter(story => {
  const normalized = normalizeUrl(story.url);
  if (seen.has(normalized)) {
    return false;
  }
  seen.add(normalized);
  return true;
});

console.log('🔀 Merge: After dedup:', uniqueStories.length, 'unique stories');

// Sort by score (descending)
uniqueStories.sort((a, b) => (b.score || 0) - (a.score || 0));

return [{
  json: {
    mergedStories: uniqueStories,
    sourceBreakdown: {
      hackernews: hnData.stories.length,
      reddit: redditData.stories.length,
      lobsters: lobstersData.stories.length,
      twitter: twitterData.stories.length
    }
  }
}];

const data = $input.first().json;
const stories = data.mergedStories || [];

// Filter for AI/ML/tech related stories
const keywords = ['ai', 'ml', 'machine learning', 'artificial intelligence', 'llm', 'gpt', 'model', 'neural', 'deep learning', 'data science', 'automation', 'robotics', 'quantum', 'tech', 'software', 'programming', 'algorithm', 'computing', 'developer', 'api', 'open source', 'security', 'privacy', 'crypto', 'blockchain', 'startup', 'cloud', 'database', 'web', 'mobile', 'app', 'code', 'language', 'framework', 'tool', 'platform'];

// Skip URLs we don't want (GitHub repos, show HN, etc)
const skipDomains = ['github.com', 'gitlab.com'];
const skipPrefixes = ['Show HN:', 'Ask HN:', 'Tell HN:'];

const relevantStories = stories.filter(story => {
  if (!story || !story.title) return false;

  const title = story.title;
  const url = story.url || '';

  // Skip show/ask/tell HN posts
  if (skipPrefixes.some(prefix => title.startsWith(prefix))) {
    return false;
  }

  // Skip GitHub/GitLab repos (prefer articles)
  if (skipDomains.some(domain => url.includes(domain))) {
    return false;
  }

  // Check for AI/tech keywords
  const titleLower = title.toLowerCase();
  return keywords.some(kw => titleLower.includes(kw));
});

console.log('✅ Agent 1: Found', relevantStories.length, 'relevant stories (filtered from', stories.length, 'total)');

if (relevantStories.length === 0) {
  console.log('⚠️ No relevant stories found, using first story as fallback');
  return [{
    json: {
      relevantStories: stories.length > 0 ? [stories[0]] : [],
      sourceBreakdown: data.sourceBreakdown
    }
  }];
}

console.log('✅ Returning', relevantStories.length, 'relevant stories for duplicate check');
return [{
  json: {
    relevantStories: relevantStories,
    sourceBreakdown: data.sourceBreakdown
  }
}];

const relevantStoriesData = $("Filter for AI/Tech Topics").first().json;
const relevantStories = relevantStoriesData.relevantStories || [];
const sourceBreakdown = relevantStoriesData.sourceBreakdown || {};

const recentPostsResponse = $input.first().json;
let recentPosts = [];
if (recentPostsResponse.posts) {
  recentPosts = recentPostsResponse.posts;
  console.log('📡 Agent 1: Blog API returned {posts: [...]} format');
} else if (Array.isArray(recentPostsResponse)) {
  recentPosts = recentPostsResponse;
  console.log('📡 Agent 1: Blog API returned direct array format');
} else {
  console.log('⚠️ Agent 1: Unknown Blog API response format:', typeof recentPostsResponse);
  recentPosts = [];
}

console.log('🔍 Agent 1: relevantStories:', relevantStories.length);
console.log('🔍 Agent 1: recentPosts:', recentPosts.length);

if (relevantStories.length === 0) {
  throw new Error('No relevant stories found from any source');
}

// Enhanced duplicate detection
function checkDuplicate(storyTitle, postTitle) {
  const storyWords = storyTitle.toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 3);
  const postWords = postTitle.toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 3);

  const wordMatches = storyWords.filter(w => postWords.includes(w)).length;
  const wordOverlap = wordMatches / Math.min(storyWords.length, postWords.length);
  const isDuplicateByWords = wordOverlap > 0.4;

  const storyKeyWords = storyTitle.split(/[^a-zA-Z0-9]+/).filter(w =>
    w.length > 5 || /^[A-Z]/.test(w)
  ).map(w => w.toLowerCase());
  const postKeyWords = postTitle.split(/[^a-zA-Z0-9]+/).filter(w =>
    w.length > 5 || /^[A-Z]/.test(w)
  ).map(w => w.toLowerCase());

  const keyMatches = storyKeyWords.filter(w => postKeyWords.includes(w));
  const isDuplicateByKeys = keyMatches.length >= 2;

  return isDuplicateByWords || isDuplicateByKeys;
}

// Find first non-duplicate story
let selectedStory = null;
let selectedIndex = -1;

for (let i = 0; i < relevantStories.length; i++) {
  const story = relevantStories[i];
  console.log('\n🔎 Checking story #' + (i + 1) + ':', story.title?.substring(0, 60));

  const isDuplicate = recentPosts.length > 0 && recentPosts.some(post => 
    checkDuplicate(story.title || '', post.title || '')
  );

  if (!isDuplicate) {
    selectedStory = story;
    selectedIndex = i;
    console.log('✅ Agent 1: Selected story #' + (i + 1) + ' from', story.source, ':', story.title);
    break;
  } else {
    console.log('⏭️ Agent 1: Story #' + (i + 1) + ' is duplicate, skipping');
  }
}

if (!selectedStory) {
  console.log('\n🛑 Agent 1: All', relevantStories.length, 'stories are duplicates of recent posts');
  throw new Error('All ' + relevantStories.length + ' relevant stories are duplicates of recent blog posts.');
}

return [{
  json: {
    selectedStory: selectedStory,
    selectedIndex: selectedIndex,
    totalRelevantStories: relevantStories.length,
    recentPostsCount: recentPosts.length,
    sourceBreakdown: sourceBreakdown
  }
}];

const data = $input.first().json;
const story = data.selectedStory;

const topic = story.title || 'AI and Technology Trends';
const url = story.url || '';

console.log('✅ Agent 1: Final selection - Story #' + (data.selectedIndex + 1) + ' of ' + data.totalRelevantStories);
console.log('✅ Agent 1: Topic:', topic);
console.log('✅ Agent 1: Source:', story.source);
console.log('✅ Agent 1: URL:', url);

const timestamp = new Date().toISOString();

return [{
  json: {
    topic: topic,
    url: url,
    style: 'accessible-explanation',
    length: 'short',
    angle: 'general overview',
    timestamp: timestamp,
    phase: 'PHASE 5 - Multi-Source Topic Discovery',
    source: story.source,
    sourceScore: story.score,
    selectedIndex: data.selectedIndex,
    totalRelevantStories: data.totalRelevantStories,
    recentPostsChecked: data.recentPostsCount,
    sourceBreakdown: data.sourceBreakdown
  }
}];
